from decimal import Decimal, InvalidOperation, ROUND_DOWN


class Group:
    def __init__(self, members: list[str]) -> None:
        self._balances = {member: Decimal("0") for member in members}

    def add_expense(
        self,
        payer: str,
        amount: float,
        participants: list[str] | None = None,
    ) -> None:
        if payer not in self._balances:
            raise ValueError("Payer is not a group member")

        try:
            total = Decimal(str(amount))
        except (InvalidOperation, ValueError):
            raise ValueError("Amount must be a positive finite number") from None
        if not total.is_finite() or total <= 0:
            raise ValueError("Amount must be a positive finite number")

        if participants is None:
            participants = list(self._balances)
        else:
            participants = list(dict.fromkeys(participants))

        if not participants:
            raise ValueError("An expense must have at least one participant")
        if any(member not in self._balances for member in participants):
            raise ValueError("All participants must be group members")

        share = (total / len(participants)).quantize(
            Decimal("0.01"), rounding=ROUND_DOWN
        )

        # Any remainder beyond the equal cent shares is borne by the payer.
        self._balances[payer] += share * len(participants)
        for member in participants:
            self._balances[member] -= share

    def balances(self) -> dict[str, float]:
        return {member: float(balance) for member, balance in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        minimum = Decimal("1.00")
        debtors = [
            [member, -balance]
            for member, balance in self._balances.items()
            if balance <= -minimum
        ]
        creditors = [
            [member, balance]
            for member, balance in self._balances.items()
            if balance >= minimum
        ]
        debtors.sort(key=lambda entry: entry[1], reverse=True)
        creditors.sort(key=lambda entry: entry[1], reverse=True)

        payments = []
        i = j = 0
        while i < len(debtors) and j < len(creditors):
            amount = min(debtors[i][1], creditors[j][1])
            payments.append((debtors[i][0], creditors[j][0], float(amount)))
            debtors[i][1] -= amount
            creditors[j][1] -= amount

            if debtors[i][1] < minimum:
                i += 1
            if creditors[j][1] < minimum:
                j += 1

        return payments
